async function changeFollowup(id,status){let found;db.interactions.forEach(i=>(i.followups||[]).forEach(f=>{if(f.id===id)found={i,f}}));const assigned=(db.assignedFollowups||[]).find(f=>f.id===id);if(!found&&!assigned){toast('This action is no longer available. Refresh and try again.');renderPage();return}const priorStatus=found?.f.status||assigned?.status;if(isAdmin()){if(!found){toast('Could not find this action. Refresh and try again.');renderPage();return}found.f.status=status;try{const response=await fetch('/api/state',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:db})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save the action status');localStorage.setItem(STORE,JSON.stringify(db));renderPage();toast(`Action marked ${status.toLowerCase()}`)}catch(error){found.f.status=priorStatus;renderPage();toast(error.message||'Could not save the action status')}return}const interactionId=found?.i.id||assigned.interactionId;try{const response=await fetch('/api/followup',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({interactionId,followupId:id,status})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not update this action');const refreshed=await fetch('/api/state',{credentials:'same-origin'});if(refreshed.ok){const payload=await refreshed.json();if(payload.state)db=payload.state}if(!found&&assigned)assigned.status=status;else if(found)found.f.status=status;localStorage.setItem(STORE,JSON.stringify(db));renderPage();toast(`Action marked ${status.toLowerCase()}`)}catch(error){if(found)found.f.status=priorStatus;else if(assigned)assigned.status=priorStatus;renderPage();toast(error.message||'Could not update this action')}}
