function cancelMeeting(id){const m=db.meetings.find(x=>x.id===id);if(!m||(!isAdmin()&&m.owner!==user().id))return;if(confirm('Cancel this planned meeting?')){m.status='Canceled';const interaction=visibleInteractions().find(i=>i.id===m.interactionId||i.meetingId===m.id);if(interaction){interaction.meetingId='';interaction.nextMeeting='';interaction.nextMeetingTime='';interaction.nextAgenda='';if(interaction.nextStepType==='Meeting scheduled')interaction.nextStepType='Yet to be decided'}save();renderPage();toast('Meeting canceled')}}
